import os, glob

def check_dir(d):
    files = glob.glob(f"/workspace/product/history/{d}/*.md")
    print(f"Total files in {d}: {len(files)}")
    sizes = {}
    for f in files:
        sz = os.path.getsize(f)
        sizes[sz] = sizes.get(sz, 0) + 1
    # print small files or unusual sizes
    print("Unusual sizes (< 500 bytes or > 2000 bytes):")
    for f in sorted(files):
        sz = os.path.getsize(f)
        if sz < 500 or sz > 2000:
            print(f"  {os.path.basename(f)}: {sz} bytes")

for d in ["actions", "evidence", "operations", "releases", "support"]:
    check_dir(d)
