import os, glob

keywords = ["September", "mobile", "Android", "phone", "draft", "waiting", "quiet digest", "Sunday Room", "Focus Shelf", "status filter"]
matches = {k: set() for k in keywords}

for root, _, files in os.walk("/workspace/product"):
    for f in files:
        path = os.path.join(root, f)
        try:
            with open(path) as fp:
                text = fp.read()
                for k in keywords:
                    if k.lower() in text.lower():
                        matches[k].add(os.path.relpath(path, "/workspace/product"))
        except Exception:
            pass

for k, v in matches.items():
    print(f"=== {k} ({len(v)} files) ===")
    # if fewer than 15 files, print them
    if len(v) < 15:
        for p in sorted(v):
            print(f"  {p}")
    else:
        # print non-operations / non-support if lots
        special = [p for p in v if not p.startswith("history/operations") and not p.startswith("history/evidence") and not p.startswith("history/actions")]
        print(f"  Top special: {special}")
'

